const LINES=[
  {name:'Ore Crusher',base:10,rate:1,unlock:0},{name:'Smelter',base:100,rate:8,unlock:25},
  {name:'Parts Press',base:850,rate:50,unlock:250},{name:'Packing Unit',base:6500,rate:280,unlock:2500}
];
const CONTRACTS=[{name:'FIRST BATCH',goal:100,reward:40},{name:'STEADY SUPPLY',goal:1500,reward:450},{name:'MASS MARKET',goal:20000,reward:6000},{name:'CITY CONTRACT',goal:250000,reward:90000}];
const fresh=()=>({money:0,lifetime:0,lines:[0,0,0,0],multiplier:1,globalLevel:0,contract:0,lastSeen:Date.now()});
let state=load(),toastTimer;const $=id=>document.getElementById(id);
function load(){try{const old=JSON.parse(localStorage.getItem('shift-save')||'{}');return {...fresh(),...old,lines:Array.isArray(old.lines)?old.lines:[0,0,0,0]}}catch{return fresh()}}
function save(){state.lastSeen=Date.now();localStorage.setItem('shift-save',JSON.stringify(state))}
function fmt(n){if(n<1000)return '$'+Math.floor(n).toLocaleString();for(const [s,v] of [['T',1e12],['B',1e9],['M',1e6],['K',1e3]])if(n>=v)return '$'+(n/v).toFixed(n/v>=100?0:n/v>=10?1:2)+s}
function output(){return LINES.reduce((sum,l,i)=>sum+l.rate*state.lines[i],0)*state.multiplier}function price(i){return Math.floor(LINES[i].base*Math.pow(1.16,state.lines[i]))}function tap(){return Math.max(1,Math.floor(1+output()*.08))}function add(n){state.money+=n;state.lifetime+=n}
function notify(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),1800)}
function renderMachines(){$('machineLayer').innerHTML=LINES.map((line,i)=>{const open=state.lifetime>=line.unlock,level=state.lines[i],cost=price(i);return `<button class="machine-button ${open?'':'locked'} ${level?'active':''}" data-machine="${i}" ${open?'':'disabled'}><small>${open?`MACHINE 0${i+1}`:`UNLOCK ${fmt(line.unlock)}`}</small><strong>${open?line.name:'LOCKED'}</strong><b>${open?`LV ${level} · ${fmt(cost)}`:''}</b></button>`}).join('');document.querySelectorAll('[data-machine]').forEach(el=>el.onclick=()=>buy(Number(el.dataset.machine)))}
function renderCrates(){const count=Math.min(3,Math.ceil(state.lines.reduce((a,b)=>a+b,0)/3));$('crateTrack').innerHTML=Array.from({length:count},()=>'<span class="crate">📦</span>').join('');$('factory').classList.toggle('running',output()>0)}
function render(){$('money').textContent=fmt(state.money);$('perSecond').textContent=fmt(output())+'/sec';$('tapValue').textContent=fmt(tap());const c=CONTRACTS[state.contract];if(c){$('contractName').textContent=c.name;$('contractReward').textContent='+'+fmt(c.reward);$('contractProgress').textContent=`${fmt(Math.min(state.lifetime,c.goal))} / ${fmt(c.goal)}`;$('contractFill').style.width=Math.min(100,state.lifetime/c.goal*100)+'%';$('claimButton').disabled=state.lifetime<c.goal}else{$('contractName').textContent='ALL ORDERS FILLED';$('contractReward').textContent='✓';$('contractProgress').textContent='COMPLETE';$('contractFill').style.width='100%';$('claimButton').disabled=true}$('upgradeCost').textContent=fmt(Math.floor(250*Math.pow(4,state.globalLevel)));renderMachines();renderCrates();$('hint').textContent=state.lines.some(Boolean)?'Tap a machine to upgrade it':'Tap a machine to build it'}
function buy(i){const cost=price(i);if(state.money<cost)return notify(`Need ${fmt(cost-state.money)} more`);state.money-=cost;state.lines[i]++;notify(`${LINES[i].name} · level ${state.lines[i]}`);pulse();render();save()}function pulse(){const el=$('factory');el.classList.remove('bump');void el.offsetWidth;el.classList.add('bump')}
function manual(){const value=tap();add(value);pulse();const n=document.createElement('span');n.className='float';n.textContent='+'+fmt(value);$('floatLayer').append(n);setTimeout(()=>n.remove(),850);render();save()}
function boost(){const cost=Math.floor(250*Math.pow(4,state.globalLevel));if(state.money<cost)return notify(`Need ${fmt(cost-state.money)} more`);state.money-=cost;state.globalLevel++;state.multiplier=Math.pow(1.25,state.globalLevel);notify('All machines boosted');render();save()}
function claim(){const c=CONTRACTS[state.contract];if(!c||state.lifetime<c.goal)return;state.money+=c.reward;state.contract++;notify(`${fmt(c.reward)} order bonus`);render();save()}
$('crankButton').onclick=manual;$('globalUpgrade').onclick=boost;$('claimButton').onclick=claim;$('resetButton').onclick=()=>$('resetModal').hidden=false;$('cancelReset').onclick=()=>$('resetModal').hidden=true;$('confirmReset').onclick=()=>{state=fresh();save();$('resetModal').hidden=true;notify('Factory reset');render()};document.addEventListener('keydown',e=>{if(e.code==='Space'&&e.target===document.body){e.preventDefault();manual()}});
const away=Math.min(14400,(Date.now()-state.lastSeen)/1000),offline=output()*away;if(offline>=1){add(offline);setTimeout(()=>notify(`While away: ${fmt(offline)}`),300)}
setInterval(()=>{add(output()/4);$('money').textContent=fmt(state.money);const c=CONTRACTS[state.contract];if(c){$('contractProgress').textContent=`${fmt(Math.min(state.lifetime,c.goal))} / ${fmt(c.goal)}`;$('contractFill').style.width=Math.min(100,state.lifetime/c.goal*100)+'%';$('claimButton').disabled=state.lifetime<c.goal}},250);setInterval(save,5000);window.addEventListener('beforeunload',save);render();
if(document.modelContext?.registerTool){[{name:'read_factory_status',title:'Read factory status',description:'Read cash, output, and machine levels.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({cash:Math.floor(state.money),lifetime:Math.floor(state.lifetime),perSecond:output(),lineLevels:state.lines})},{name:'run_factory_machine',title:'Run factory machine',description:'Run the central machine once.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{const value=tap();add(value);render();save();return{produced:value,cash:Math.floor(state.money)}}}].forEach(tool=>document.modelContext.registerTool(tool))}
